from typing import Callable, Dict, Hashable, List, Sequence

def inv_fun(domain: Sequence[Hashable], f: Callable[[Hashable], Hashable]):
    table: Dict[Hashable, Hashable] = {}
    for x in domain:
        y = f(x)
        if y not in table:
            table[y] = x
    default = domain[0]
    return lambda y: table.get(y, default)

def is_weak_inverse(domain, f, g) -> bool:
    return all(f(g(f(x))) == f(x) for x in domain)

domain = list(range(-4, 5))
f = lambda x: x * x
g = inv_fun(domain, f)
print('weak inverse?', is_weak_inverse(domain, f, g))
print('weak successes =', sum(1 for x in domain if f(g(f(x))) == f(x)), '/', len(domain))

from typing import Callable, Dict, List, Sequence

def image(domain, f): 
    seen=[]; s=set()
    for x in domain:
        y=f(x)
        if y not in s: s.add(y); seen.append(y)
    return seen

def all_inverters(domain, f):
    img=image(domain,f); out=[]
    def build(i, partial):
        if i==len(img):
            t=dict(partial); out.append(lambda y,t=t: t.get(y,domain[0])); return
        for x in domain:
            partial[img[i]]=x; build(i+1, partial)
        partial.pop(img[i], None)
    build(0, {}); return out

domain=list(range(6)); f=lambda x: x%3
best=max(len([x for x in domain if g(f(x))==x]) for g in all_inverters(domain,f))
print('|Im f| =', len(image(domain,f)), ' max exact over all inverters =', best)

